// Go: fetch and use an SVID via the SPIFFE Workload API
// Requires: github.com/spiffe/go-spiffe/v2
package main

import (
    "context"
    "net/http"
    "github.com/spiffe/go-spiffe/v2/spiffetls/tlsconfig"
    "github.com/spiffe/go-spiffe/v2/workloadapi"
)

func newMTLSClient(ctx context.Context) (*http.Client, error) {
    // Fetch X.509 SVID from SPIRE Agent (local Unix socket, no secret needed)
    source, err := workloadapi.NewX509Source(ctx)
    if err != nil {
        return nil, err
    }
    // TLS config: present our SVID, verify peer SVIDs from same trust domain
    tlsCfg := tlsconfig.MTLSClientConfig(source, source,
        tlsconfig.AuthorizeSPIFFEID("spiffe://example.org/payments/api"))
    return &http.Client{Transport: &http.Transport{TLSClientConfig: tlsCfg}}, nil
}

# Cloudflare Access ZTNA policy (Terraform)
resource "cloudflare_access_application" "internal_wiki" {
  zone_id          = var.zone_id
  name             = "Internal Engineering Wiki"
  domain           = "wiki.internal.example.com"
  session_duration = "4h"
}

resource "cloudflare_access_policy" "eng_team" {
  application_id = cloudflare_access_application.internal_wiki.id
  zone_id        = var.zone_id
  name           = "Engineering team only"
  precedence     = 1
  decision       = "allow"

  include {
    # Identity: Okta group membership
    okta { identity_provider_id = var.okta_idp_id; name = ["engineering"] }
  }
  require {
    # Device posture: must have corp certificate + Crowdstrike running
    device_posture = [var.posture_rule_corp_cert, var.posture_rule_edr]
  }
}

# Flask: resource isolation policy using Fetch Metadata headers
from flask import request, abort

PUBLIC_ENDPOINTS = {"/api/v1/public", "/health"}

def fetch_metadata_isolation():
    """Reject cross-site requests to non-public endpoints."""
    path = request.path
    if path in PUBLIC_ENDPOINTS:
        return  # public API — cross-site fetch is acceptable

    sec_fetch_site = request.headers.get("Sec-Fetch-Site", "")
    sec_fetch_mode = request.headers.get("Sec-Fetch-Mode", "")

    # Allow: same-origin, top-level navigations (direct URL bar), and no header (non-browser)
    if sec_fetch_site in ("", "same-origin", "none"):
        return
    if sec_fetch_mode == "navigate" and request.method == "GET":
        return  # allow cross-site navigations (e.g., links) to GET endpoints

    abort(403)  # cross-site sub-resource request to a non-public endpoint

# Short-lived JWTs: force frequent re-evaluation (continuous verification)
from datetime import datetime, timedelta
import jwt

SECRET = "your-signing-key"
TOKEN_LIFETIME = timedelta(minutes=15)   # narrow window limits stolen-token blast radius

def issue_access_token(user_id: str, device_compliant: bool) -> str:
    if not device_compliant:
        raise PermissionError("Device posture check failed")
    payload = {
        "sub": user_id,
        "iat": datetime.utcnow(),
        "exp": datetime.utcnow() + TOKEN_LIFETIME,
        "device_checked_at": datetime.utcnow().isoformat(),
    }
    return jwt.encode(payload, SECRET, algorithm="ES256")
